Object.entries({"下北泽站":[{"type":"闲聊","people":"你、任何一位街坊","event":"语言小镇任务「初次见面」：走近任何一位居民,用日语打招呼,并告诉对方你的名字。","lines":[["你","こんにちは!私は◯◯です。よろしくお願いします。","konnichiwa! watashi wa ◯◯ desu. yoroshiku onegai shimasu.","你好！我是◯◯。请多关照。"]],"words":[],"culture":"东京街区里谁都可以聊，先打招呼再介绍自己。","try":"用日语打招呼,并告诉对方你的名字。"},{"type":"求助","people":"你、ゆきさん（车站站务员）","event":"语言小镇任务「问路」：向车站的ゆきさん用日语打听:去涩谷(渋谷)该怎么走、坐什么线。","lines":[["ゆきさん","こんにちは。何かお困りですか?道案内いたしましょうか?","konnichiwa. nanika o-komari desu ka? michi annai itashimashō ka?","您好。遇到什么困难了吗？需要我帮您指路吗？"],["你","すみません、渋谷までどうやって行きますか?","sumimasen, Shibuya made dōyatte ikimasu ka?","不好意思，去涩谷怎么走？"]],"words":[],"culture":"熟悉所有线路和周边景点","try":"向车站的ゆきさん用日语打听:去涩谷(渋谷)该怎么走、坐什么线。"},{"type":"闲聊","people":"你、大輝（高中生·乐队吉他手）","event":"语言小镇任务「少年心事」：找大辉聊聊,想办法让他说出自己真正的梦想,和跟爸爸的矛盾。","lines":[["大輝","…ん?何?俺?","…n? nani? ore?","……嗯？什么？我吗？"],["你","大輝くんの夢は何?","Daiki-kun no yume wa nani?","大辉，你的梦想是什么？"]],"words":[],"culture":"对拉面店的味道其实骄傲得不行,但打死不承认,一心想去武道馆","try":"想办法让他说出自己真正的梦想,和跟爸爸的矛盾。"}],"便利店 FamiMart（下北泽）":[{"type":"买东西","people":"你、田中さん（便利店店员）","event":"语言小镇任务「便利店购物」：去便利店找田中さん,用日语买一个饭团,并问问多少钱。","lines":[["田中さん","いらっしゃいませ〜!何かお探しですか?","irasshaimase~! nanika o-sagashi desu ka?","欢迎光临～！您在找什么吗？"],["你","おにぎりをひとつください。いくらですか?","onigiri o hitotsu kudasai. ikura desu ka?","请给我一个饭团。多少钱？"]],"words":[],"culture":"性格温和絮叨,对便当和饭团的知识如数家珍,记得每个熟客爱买什么","try":"用日语买一个饭团,并问问多少钱。"}],"一番拉面店":[{"type":"买东西","people":"你、佐藤さん（拉面店老板）","event":"语言小镇任务「点一碗拉面」：去一番拉面,用日语点餐,并请佐藤师傅推荐招牌。","lines":[["佐藤さん","らっしゃい!腹減ってるか?うちの豚骨は日本一だぜ!","rasshai! hara hetteru ka? uchi no tonkotsu wa Nihon-ichi da ze!","来啦！饿了吧？我家的豚骨可是日本第一！"],["你","おすすめは何ですか?それをください!","osusume wa nan desu ka? sore o kudasai!","推荐什么？就要那个！"]],"words":[],"culture":"嗓门大、性格豪爽,像个热心大哥,对食材极其讲究,聊起拉面停不下来","try":"用日语点餐,并请佐藤师傅推荐招牌。"}],"稻荷神社":[{"type":"闲聊","people":"你、初音おばあちゃん（花店奶奶）","event":"语言小镇任务「祭典之夜」：神社祭典期间(单数日 19:00-22:00),去祭典上找初音奶奶,请她讲一个关于祭典或往事的故事。","lines":[["初音おばあちゃん","あらあら、いらっしゃい。今日はいいお花が入ってますよ。","ara ara, irasshai. kyō wa ii o-hana ga haittemasu yo.","哎呀哎呀，欢迎。今天进了很好的花哦。"],["你","お祭りの思い出を聞かせてください。","o-matsuri no omoide o kikasete kudasai.","请给我讲讲祭典的回忆。"]],"words":[],"culture":"温柔健谈,是全街善意八卦的中转站——谁家孩子考学、谁最近瘦了,她都知道,但只说好话","try":"去祭典上找初音奶奶,请她讲一个关于祭典或往事的故事。"},{"type":"闲聊","people":"你、さくら、初音おばあちゃん、ゆきさん、大野巡査、大輝、健太","event":"🎆 小镇活动「神社祭典」（19点–22点）：稻荷神社夏祭:红灯笼、屋台小吃、金鱼捞,镇上的人都来了。","lines":[["さくら","やっほー!また会ったね!ねえ、ちょっとモデルになってくれない?","yahhō! mata atta ne! nē, chotto moderu ni natte kurenai?","哟吼！又见面了！喂，能给我当一下模特吗？"]],"words":[],"culture":"在祭典的屋台之间逛,捞金鱼、吃苹果糖、看灯笼","try":"问问大家祭典上有什么好吃的、好玩的。"}],"弄堂口":[{"type":"闲聊","people":"你、任何一位街坊","event":"语言小镇任务「打个招呼」：用中文向任何一位街坊问好,并介绍自己叫什么。","lines":[["你","你好!我叫◯◯,刚来上海。","","你好!我叫◯◯,刚来上海。"]],"words":[],"culture":"上海街区里谁都可以聊，先打招呼再介绍自己。","try":"并介绍自己叫什么。"},{"type":"闲聊","people":"你、任何一位街坊","event":"语言小镇任务「学句上海话」：请任何一位街坊教你一句上海话,并当场用出来。","lines":[["你","能教我一句上海话吗?","","能教我一句上海话吗?"]],"words":[],"culture":"上海街区里谁都可以聊，先打招呼再介绍自己。","try":"并当场用出来。"},{"type":"闲聊","people":"你、王阿姨、老金、阿香、小马、美美、晓芸","event":"🏮 小镇活动「弄堂夜市」（18.5点–22点）：弄堂夜市开张:生煎、烤串、糖粥,灯串把石板路照得发亮。","lines":[["王阿姨","哟,又是侬呀!今朝想吃点啥?","",""]],"words":[],"culture":"在夜市里摆摊、逛吃,吆喝声、香气和灯串混在一起","try":"问出至少三种夜市小吃的名字。"}],"王家小笼包":[{"type":"买东西","people":"你、王阿姨（小笼包店老板娘）","event":"语言小镇任务「买小笼包」：向王阿姨买一笼小笼包,并问她\"小笼包怎么吃才不烫嘴\"。","lines":[["王阿姨","小囡,侬好呀!来一笼小笼包伐?刚出锅额,烫哦!","","小囡,侬好呀!来一笼小笼包伐?刚出锅额,烫哦!"],["你","阿姨,来一笼小笼包!怎么吃不烫嘴呀?","","阿姨,来一笼小笼包!怎么吃不烫嘴呀?"]],"words":[],"culture":"热情爽快,嗓门大,爱拉家常,见谁都喊\"小囡\"","try":"并问她\"小笼包怎么吃才不烫嘴\"。"}],"弄堂菜场":[{"type":"讨价还价","people":"你、阿香（菜场摊主）","event":"语言小镇任务「讨价还价」：去菜市场找阿香买样菜,试着用中文砍砍价(哪怕砍不下来)。","lines":[["阿香","小囡买菜伐?今朝鸡毛菜嫩得来!","","小囡买菜伐?今朝鸡毛菜嫩得来!"],["你","这个怎么卖?便宜一点好不好?","","这个怎么卖?便宜一点好不好?"]],"words":[],"culture":"刀子嘴豆腐心,砍价砍得凶,称完总会抓把葱塞给你","try":"试着用中文砍砍价(哪怕砍不下来)。"}],"街心公园":[{"type":"闲聊","people":"你、张爷爷（退休语文教师）","event":"语言小镇任务「成语挑战」：请张爷爷教你一个成语,并用它造一个句子。","lines":[["张爷爷","小朋友,过来过来,会下象棋吗?","","小朋友,过来过来,会下象棋吗?"],["你","张爷爷,教我一个成语吧!","","张爷爷,教我一个成语吧!"]],"words":[],"culture":"慈祥健谈,一肚子上海老故事和成语典故,说话慢条斯理,爱考人成语,夸人必说\"孺子可教\"","try":"并用它造一个句子。"}],"弄堂奶茶店":[{"type":"闲聊","people":"你、美美（奶茶店店员）","event":"语言小镇任务「夜市之约」：弄堂夜市期间(双数日 18:30-22:00),在夜市找美美,问出至少三种小吃的名字。","lines":[["美美","欢迎光临~今天想喝点什么?我们家杨枝甘露绝了!","","欢迎光临~今天想喝点什么?我们家杨枝甘露绝了!"],["你","这些小吃都叫什么名字呀?","","这些小吃都叫什么名字呀?"]],"words":[],"culture":"说话快、爱用网络流行语(绝了、真的假的、yyds),发现你是学中文的会立刻切换\"教学模式\"耐心解释","try":"在夜市找美美,问出至少三种小吃的名字。"}]}).forEach(([k,v])=>{ (PLACE_EVENTS[k] = PLACE_EVENTS[k] || []).push(...v); });
[["fang","lt_wangayi","常来拍王阿姨包小笼包的视频","拍过她的店，视频里叫她“上海最会包小笼的阿姨”"],["emma","lt_zhangyeye","跟张爷爷学成语，被抽查时总答不上来","教这个法国学生成语，说她“孺子可教”"],["zhou","lt_xiaoyun","给晓芸的街坊专栏当实习记者","带新闻系的周晓采访街坊"],["wang","lt_xiaoma","午饭常点外卖，小马送得最准时","常给陆家嘴的王蕾送午饭"],["chen","lt_laozhao","每个月去德胜理发店剪一次头","给网球教练陈一鸣剪寸头"]].forEach(([a,b,ha,hb])=>{ const A = NPCS.find(n=>n.id===a), B = NPCS.find(n=>n.id===b); if (A && B){ A.rel.push({id:b, how:ha}); B.rel.push({id:a, how:hb}); } });

